-- v380 — LE CATALOGUE VERSÉ EN BASE (01/10/2026)
--
-- Les données de v379. 108 formations, 761 modules, 1 956 leçons, extraites de
-- `FORMATIONS_CATALOG` dans `SportVision-OS-Full.html` par un lecteur de littéral JavaScript, pas
-- recopiées à la main : une recopie de 1 956 lignes se trompe, et on ne saurait pas où.
--
-- CE QUI N'EST PAS RECOPIÉ : l'XP du HTML. Il diverge des 108 lignes de `formation_rewards`, et
-- c'est VOULU (`migration-formation-v1-bareme-xp.sql`, 09/09/2026 : division par 4 en base seule,
-- à la demande de Fouka). La certification non plus : elle est dans `formation_rewards`.
--
-- `ordre` est le rang du HTML. Il n'est pas alphabétique et il porte une intention : les trois
-- modules d'accueil obligatoires viennent en premier.
--
-- RELANÇABLE. Chaque insertion finit par un `on conflict … do update` : rejouer la migration
-- remet le catalogue à l'état du HTML, sans doublon et sans perdre les identifiants des modules
-- (donc sans casser les leçons qui les référencent).
--
-- LE CONTRÔLE FINAL N'EST PAS DÉCORATIF. Il compare le nombre de leçons versées, formation par
-- formation, à `formation_rewards.total_lecons` — le nombre que `rpc_complete_formation` exige
-- pour délivrer une certification. Si les deux ne coïncident pas, la transaction est annulée :
-- un catalogue qui compte 95 leçons là où le serveur en attend 96 produit une formation qu'on ne
-- peut jamais terminer, et l'écran ne le dirait pas.

begin;

-- Les 108 formations. `ordre` est le rang du HTML : c'est l'ordre dans lequel l'OS les
-- presente, et il porte une progression (les trois modules d'accueil d'abord).
insert into public.formations (id, titre, categorie, icone, niveau, type, duree, formateur, obligatoire, description, roles, grade_minimum, publiee, ordre) values
  ('sv-culture', 'Culture & standards SportVision', 'Culture SportVision', '🎯', 'Débutant', 'en_ligne', '45 min', 'Équipe SportVision', true, 'Comprendre les valeurs, la vision et les standards qualité de SportVision. Module d''accueil indispensable avant toute mission.', null, null, true, 0),
  ('sv-securite', 'Sécurité et gestion du matériel', 'Matériel', '🔧', 'Débutant', 'en_ligne', '30 min', 'Équipe SportVision', true, 'Règles essentielles pour manipuler, transporter et restituer le matériel SportVision en bon état.', null, null, true, 1),
  ('sv-comportement', 'Comportement en prestation', 'Relation client', '🤝', 'Débutant', 'en_ligne', '30 min', 'Équipe SportVision', true, 'Les règles de savoir-être et de communication avec les clubs, les familles et les joueurs lors des prestations.', null, null, true, 2),
  ('photo-bases', 'Bases de la photographie sportive', 'Photographie', '📷', 'Débutant', 'hybride', '3h', 'Fouka', true, 'Les fondamentaux de la photographie en contexte sportif : exposition, autofocus, déclenchement, cadrage.', array['photo','admin']::text[], null, true, 3),
  ('cert-photo-video-complet', 'Photographe-Vidéaste Sportif Complet', 'Certification complète', '🎬', 'Complet', 'hybride', '72h', 'Fouka', false, 'Parcours complet et autonome : photo, vidéo, postproduction, montage, audio et colorimétrie pour devenir photographe-vidéaste sportif SportVision, de la posture terrain jusqu''à la certification finale. 16 modules, cours complets, cas pratiques et quiz.', array['photo']::text[], null, true, 4),
  ('cert-responsable-production-complet', 'Responsable Production Complet', 'Certification complète', '🧭', 'Complet', 'hybride', '42h', 'Fouka', false, 'Parcours complet et autonome pour piloter la production SportVision : SportVision OS, planning, management d''équipe, kits et matériel, gestion de crise, contrôle qualité, coordination inter-pôles, KPI et croissance jusqu''à 15 collaborateurs. 12 modules, cours complets, cas pratiques et quiz.', array['prod']::text[], null, true, 5),
  ('cert-commercial-complet', 'Commercial SportVision Complet', 'Certification complète', '📈', 'Complet', 'hybride', '42h', 'Fouka', false, 'Parcours complet et autonome pour prospecter, qualifier, présenter les offres et fidéliser les clients de SportVision : rôle de l''apporteur d''affaires, éthique et conformité, offres et commissions, CRM et pipeline, ciblage, prospection multicanale, découverte, pitch, objections, closing et pilotage commercial jusqu''à la certification finale. 12 modules, cours complets, cas pratiques et quiz.', array['com']::text[], null, true, 6),
  ('cert-secretaire-complet', 'Secrétaire SportVision Complet', 'Certification complète', '📋', 'Complet', 'hybride', '53h30', 'Fouka', false, 'Parcours complet et autonome pour organiser l''administratif de SportVision : rôle de la secrétaire, communication et accueil, SportVision OS et qualité des données, CRM et pipeline administratif, planification et calendrier, devis et contrats, facturation et impayés, gestion des freelances, Drive, Gmail et messagerie, administration d''événements, contrôle qualité et RGPD, avec deux spécialisations (agenda avancé, recrutement et intégration) jusqu''à la certification finale. 14 modules, cours complets, cas pratiques et quiz.', array['sec']::text[], null, true, 7),
  ('photo-sony-a7', 'Maîtrise du Sony A7 IV', 'Matériel', '📸', 'Intermédiaire', 'hybride', '1h30', 'Fouka', false, 'Apprenez à préparer, configurer et utiliser le Sony A7 IV selon les procédures SportVision, en photographie comme en vidéo : commandes du boîtier, préparation du matériel, exposition, autofocus et suivi, préréglages photo et vidéo SportVision, raccourcis, sécurisation des médias et restitution du kit, jusqu''à la certification Opérateur Sony A7 IV.', array['photo']::text[], null, true, 8),
  ('sec-crm-05', 'Secrétariat 05 — Gestion des fiches clients et portefeuille administratif', 'Secrétariat', '🗂️', 'Intermédiaire', 'hybride', '7h', 'Fouka', false, 'Apprendre à maintenir une base clients fiable, complète, sans doublons et facilement exploitable par le commercial, la production, la comptabilité et la direction : distinguer client/contact/demande/prestation, créer et vérifier les fiches, attribuer les rôles des contacts, gérer l''historique et les notes factuelles, suivre le cycle de vie du client, organiser le portefeuille, détecter doublons et risques, préparer les relances et assurer la continuité des dossiers, jusqu''à la certification CERT-SEC-05.', array['sec']::text[], null, true, 9),
  ('cm-sport-01', 'Community management sportif', 'Communication et réseaux sociaux', '📱', 'Intermédiaire à avancé', 'hybride', '9h', 'Fouka', false, 'Construire, produire, publier, modérer et analyser la communication numérique d''un club, d''un sportif, d''un événement ou d''un client SportVision. Le Community Manager ne se contente pas de « poster du contenu » : il pilote un cycle complet — stratégie, calendrier, production, validation, publication, modération, analyse, amélioration — jusqu''à la certification CERT-CM.', array['cm']::text[], null, true, 10),
  ('content-sport-01', 'Création de contenus sportifs pour les réseaux sociaux', 'Création de contenu', '🎬', 'Débutant à intermédiaire', 'hybride', '3h', 'Fouka', false, 'Comprendre les formats sociaux, identifier une audience, transformer un événement en plusieurs contenus, créer un Hook, filmer verticalement, produire des formats courts, intégrer texte et sous-titres, créer un rythme, intégrer un sponsor et terminer par un appel à l''action — jusqu''à la certification CERT-VERT.', array['photo','cm']::text[], null, true, 11),
  ('design-sport-01', 'Création de visuels sportifs', 'Création de contenu', '🎨', 'Débutant à intermédiaire', 'hybride', '3h30', 'Fouka', false, 'Comprendre le brief, construire une hiérarchie visuelle, utiliser typographie et couleurs, choisir et préparer les images, composer, intégrer les sponsors, produire les bons formats et respecter les templates SportVision — jusqu''à la certification CERT-VISUEL. La formation ne dépend d''aucun logiciel en particulier (Canva, Photoshop, Photopea, outils internes) : les principes graphiques restent prioritaires.', array['photo','cm']::text[], null, true, 12),
  ('mont-capcut-01', 'Montage vidéo sportif rapide sur CapCut', 'Montage et postproduction', '✂️', 'Débutant à intermédiaire', 'hybride', '4h', 'Fouka', false, 'Transformer rapidement des rushs sportifs en vidéos dynamiques, lisibles et professionnelles avec CapCut, sans surcharger le montage d''effets inutiles : brief, organisation des fichiers, nommage de projet, sélection des rushs, montage brut, rythme, musique, sons réels, ralentis/speed ramps, transitions, images clés, sous-titres, direction artistique, sponsors, correction visuelle simple, déclinaisons et export — jusqu''à la certification CERT-CAPCUT. Un montage rapide est d''abord un montage préparé, organisé et structuré.', array['photo','prod','cm']::text[], null, true, 13),
  ('fusion-motion-sport-01', 'Fusion et motion design sportif sur DaVinci Resolve', 'Motion design et effets visuels', '✨', 'Intermédiaire à avancé', 'hybride', '10h', 'Fouka', false, 'Créer dans Fusion les éléments graphiques des productions SportVision : introductions, animations de logos, compositions d''équipes, tableaux de score, statistiques de joueurs, titres animés, fiches de présentation, callouts, transitions, habillages d''interviews, animations de sponsors et modèles réutilisables. Méthode SportVision en cinq principes : clarté → mouvement → identité → lisibilité → réutilisation — jusqu''à la certification CERT-FUSION-MOTION.', array['photo','prod']::text[], null, true, 14),
  ('photo-ret-01', 'Retouche photo sportive professionnelle', 'Photographie et postproduction', '🖼️', 'Intermédiaire à avancé', 'hybride', '8h', 'Fouka', false, 'Transformer une couverture sportive brute en une galerie professionnelle, cohérente et fidèle à l''événement avec Lightroom Classic, Camera Raw et Photoshop : réception et organisation, tri, développement RAW, masques et corrections locales, cohérence de série, retouche avancée non destructive, export et livraison — jusqu''à la certification CERT-RET. Équilibre à trouver entre qualité technique, cohérence de la série, identité du client, rapidité de traitement et fidélité à l''événement.', array['photo']::text[], null, true, 15),
  ('photo-ret-adv-01', 'Retouche photo sportive avancée', 'Photographie et postproduction', '🖌️', 'Avancé', 'hybride', '10h', 'Fouka', false, 'Traiter des séries sportives complexes, harmoniser plusieurs appareils, maîtriser les masques avancés, corriger les lumières difficiles et produire des images héro professionnelles sans dénaturer l''événement. Principe SportVision : corriger → harmoniser → diriger le regard → créer une identité → préserver la réalité — jusqu''à la certification CERT-RET2.', array['photo','prod']::text[], null, true, 16),
  ('lead-terrain-01', 'Responsable de prestation terrain', 'Leadership et production terrain', '🚩', 'Avancé', 'hybride', '6h', 'Fouka', false, 'Diriger l''exécution d''une prestation sur place : prise en charge du dossier, confirmation de l''équipe, retrait des kits, briefing terrain et oral, répartition des positions, supervision de la production, gestion des imprévus (panne, retard, incident client ou de sécurité), sécurisation des médias, retour, transfert, compte rendu et débriefing — jusqu''à la certification CERT-LEAD. Mission centrale : faire exécuter le briefing validé sans improvisation dangereuse et sans perdre le contrôle de l''équipe, du matériel ou des médias.', array['photo','prod']::text[], 3, true, 17),
  ('prod-tournoi-01', 'Production de tournoi et événement sportif complexe', 'Production complexe et événementiel sportif', '🏆', 'Avancé', 'hybride', '10h', 'Fouka', false, 'Coordonner une prestation comprenant plusieurs terrains, plusieurs équipes, plusieurs métiers ou plusieurs journées : qualifier la complexité, définir le périmètre SportVision, identifier les responsabilités, construire le budget et le plan de production, analyser le programme sportif, cartographier le site, construire l''organigramme, constituer les équipes, organiser rotations/kits/batteries/cartes, centre de coordination, communication d''équipe, publications en direct, sponsors, dispositifs techniques (Veo/drone/streaming), gestion des changements et incidents multisites, contrôle qualité, clôture et bilan — jusqu''à la certification CERT-TOURNOI. Mission : transformer l''événement en un système pilotable, sans chercher à tout réaliser soi-même.', array['prod']::text[], 3, true, 18),
  ('stab-gimbal-01', 'Maîtrise du stabilisateur', 'Matériel et captation technique', '⚖️', 'Intermédiaire', 'hybride', '4h', 'Fouka', false, 'Configurer, équilibrer, calibrer et utiliser un stabilisateur (DJI RS 3 Mini, RS 4, RS 4 Pro, RS 4 Mini et équivalents validés) en toute sécurité sur le terrain sportif : équilibrage des trois axes, calibration, modes PF/PTF/FPV/verrouillage, mouvements (push-in, suivi, révélation, rotation), marche opérateur, sécurité en présence de joueurs et de public, orientation horizontale et verticale — jusqu''à la certification CERT-STAB.', array['photo','cm']::text[], null, true, 19),
  ('light-acc-01', 'Gestion de la lumière et des accessoires', 'Matériel et captation technique', '💡', 'Débutant à intermédiaire', 'hybride', '6h', 'Fouka', false, 'Maîtriser la lumière naturelle et artificielle, l''éclairage trois points, la température de couleur, les modeleurs, les filtres ND, les supports (pieds, monopode, trépied), l''audio et les accessoires, la gestion de l''énergie et la protection météo — jusqu''à la certification CERT-LIGHT-ACC.', array['photo','cm']::text[], null, true, 20),
  ('pv-avance-01', 'Workflow professionnel : ranger, nommer, sauvegarder et livrer sans perdre de temps', 'Bloc A - Vitesse et organisation', '🗂️', 'Avancé', 'hybride', '3h + 1 mission', 'Fouka', false, 'Construire un dossier de mission identique pour toute l''équipe, éviter les fichiers introuvables et doublons, préparer un montage ou une sélection en quelques minutes, et sauvegarder avant toute suppression de carte mémoire.', array['photo']::text[], 2, true, 21),
  ('pv-avance-02', 'Tri photo ultra-rapide : sélectionner les images fortes sans surcharger la livraison', 'Bloc A - Vitesse et organisation', '🖼️', 'Avancé', 'hybride', '4h + 1 match', 'Fouka', false, 'Réduire le temps de tri après un match, distinguer image techniquement correcte et image réellement utile, créer une sélection variée sans doublons avec drapeaux, étoiles et comparaison dans Lightroom.', array['photo']::text[], 2, true, 22),
  ('pv-avance-03', 'Sélection des rushs : dérusher vite et construire une banque de plans utile', 'Bloc A - Vitesse et organisation', '🎞️', 'Avancé', 'hybride', '4h + 1 entraînement', 'Fouka', false, 'Identifier rapidement les meilleurs plans, noter les moments forts sans multiplier les visionnages, créer des sous-sélections par histoire et par format, détecter les plans manquants avant de quitter le terrain.', array['photo']::text[], 2, true, 23),
  ('pv-avance-04', 'CapCut Desktop : maîtriser l''interface et monter deux fois plus vite', 'Bloc B - Montage CapCut avancé', '✂️', 'Avancé', 'hybride', '5h + 2 exercices', 'Fouka', false, 'Maîtriser la timeline multipiste, créer des préréglages et modèles SportVision, utiliser les raccourcis essentiels et préparer des exports adaptés à Instagram, TikTok et à la livraison client.', array['photo']::text[], 2, true, 24),
  ('pv-avance-05', 'Storytelling sportif : raconter une histoire au lieu d''empiler des actions', 'Bloc B - Montage CapCut avancé', '📖', 'Avancé', 'hybride', '4h + 1 film', 'Fouka', false, 'Construire un début, une montée et une conclusion, donner une intention émotionnelle à chaque plan, créer un hook honnête et adapter une même histoire à 15, 30 et 60 secondes.', array['photo']::text[], 2, true, 25),
  ('pv-avance-06', 'Rythme, musique, beat cuts et speed ramp pour les contenus sportifs', 'Bloc B - Montage CapCut avancé', '🎵', 'Avancé', 'hybride', '5h + 2 montages', 'Fouka', false, 'Couper sur le mouvement et sur la musique, créer une accélération lisible, utiliser le ralenti seulement lorsqu''il renforce l''action et réaliser une speed ramp fluide dans CapCut.', array['photo']::text[], 2, true, 26),
  ('pv-avance-07', 'Sound design et mixage : donner de la puissance sans saturer', 'Bloc B - Montage CapCut avancé', '🎧', 'Avancé', 'hybride', '4h + 1 mixage', 'Fouka', false, 'Nettoyer et équilibrer une voix, créer une hiérarchie musique/ambiance/effets, renforcer les impacts avec des sons réalistes et éviter saturation, souffle et variations brutales.', array['photo']::text[], 2, true, 27),
  ('pv-avance-08', 'Keyframes, masques, tracking et effets avancés dans CapCut', 'Bloc B - Montage CapCut avancé', '🎛️', 'Avancé', 'hybride', '6h + 3 exercices', 'Fouka', false, 'Animer position, échelle, rotation et opacité, créer une transition par masque, suivre un joueur ou un ballon avec du texte, et flouter un visage ou une information sensible.', array['photo']::text[], 2, true, 28),
  ('pv-avance-09', 'Colorimétrie vidéo : corriger, harmoniser et créer un look SportVision', 'Bloc B - Montage CapCut avancé', '🎨', 'Avancé', 'hybride', '5h + 1 série', 'Fouka', false, 'Corriger exposition et balance des blancs, rapprocher plusieurs caméras, préserver les tons de peau et les couleurs du club, et créer un look cohérent sans écraser l''image.', array['photo']::text[], 2, true, 29),
  ('pv-avance-10', 'Sous-titres, typographie, habillage et exports sociaux', 'Bloc B - Montage CapCut avancé', '💬', 'Avancé', 'hybride', '4h + 2 formats', 'Fouka', false, 'Créer des sous-titres lisibles et corrigés, respecter la charte SportVision ou celle du client, protéger les zones couvertes par les interfaces sociales et exporter une version par plateforme.', array['photo']::text[], 2, true, 30),
  ('pv-avance-11', 'Filmer l''action sportive : anticipation, réglages et placements', 'Bloc C - Captation terrain', '🏃', 'Avancé', 'hybride', '6h + 2 matchs', 'Fouka', false, 'Anticiper l''action plutôt que la poursuivre, choisir un placement qui donne profondeur et visages, obtenir des mouvements fluides et adapter vitesse, obturation et mise au point à l''intention.', array['photo']::text[], 2, true, 31),
  ('pv-avance-12', 'Construire une shot list complète pour match, entraînement, tournoi et stage', 'Bloc C - Captation terrain', '📝', 'Avancé', 'hybride', '4h + 1 événement', 'Fouka', false, 'Préparer une couverture qui ne dépend pas du hasard, capturer les plans indispensables avant l''urgence, répartir les rôles entre plusieurs opérateurs et créer suffisamment de matière pour plusieurs contenus.', array['photo']::text[], 2, true, 32),
  ('pv-avance-13', 'Interview, témoignage et face caméra : image, lumière et son', 'Bloc C - Captation terrain', '🎙️', 'Avancé', 'hybride', '5h + 2 interviews', 'Fouka', false, 'Installer rapidement une interview propre, obtenir un son exploitable en environnement sportif, guider une personne peu à l''aise face caméra et créer du B-roll pour masquer les coupes.', array['photo']::text[], 2, true, 33),
  ('pv-avance-14', 'Photographie sportive avancée : action, émotion, netteté et composition', 'Bloc C - Captation terrain', '📸', 'Avancé', 'hybride', '6h + 2 matchs', 'Fouka', false, 'Augmenter le taux de photos fortes, choisir vitesse, autofocus et rafale selon le sport, composer rapidement sans couper l''action et créer des images utilisables en communication.', array['photo']::text[], 2, true, 34),
  ('pv-avance-15', 'Media Day d''équipe : organiser un shooting complet avant saison', 'Bloc D - Shooting et identité visuelle', '🗓️', 'Avancé', 'hybride', '7h + 1 Media Day', 'Fouka', false, 'Préparer un planning par joueur et par poste, produire photos et vidéos homogènes, créer une banque de contenus pour toute la saison et éviter les oublis de poses, sponsors et formats.', array['photo']::text[], 2, true, 35),
  ('pv-avance-16', 'Shooting individuel joueur : portrait, personnalité et contenus de pré-saison', 'Bloc D - Shooting et identité visuelle', '🌟', 'Avancé', 'hybride', '5h + 1 joueur', 'Fouka', false, 'Créer une séance cohérente avec le positionnement du joueur, produire des photos officielles, éditoriales et réseaux sociaux, diriger une personne non modèle et préparer des contenus utilisables plusieurs mois.', array['photo']::text[], 2, true, 36),
  ('pv-avance-17', 'Créer une banque de contenus club pour toute la saison', 'Bloc D - Shooting et identité visuelle', '🗃️', 'Avancé', 'hybride', '4h + projet club', 'Fouka', false, 'Transformer un tournage en ressources pour plusieurs mois, prévoir les annonces et moments de saison, classer les contenus pour que le Community Manager les retrouve et éviter tout usage inadapté.', array['photo']::text[], 2, true, 37),
  ('pv-avance-18', 'Créer une affiche avant-match et un flyer communicatif dans Canva', 'Bloc E - Design et communication', '🖌️', 'Avancé', 'hybride', '5h + 3 visuels', 'Fouka', false, 'Construire une hiérarchie visuelle claire, créer un visuel sportif dynamique sans copier, détourer et intégrer un joueur proprement, et décliner un visuel en publication, story et écran.', array['photo']::text[], 2, true, 38),
  ('pv-avance-19', 'Animer une affiche et créer un teaser de match dans CapCut', 'Bloc E - Design et communication', '🎬', 'Avancé', 'hybride', '5h + 2 teasers', 'Fouka', false, 'Transformer un visuel statique en teaser vertical, créer de la profondeur avec calques et keyframes, synchroniser l''apparition des informations et conserver lisibilité et identité du club.', array['photo']::text[], 2, true, 39),
  ('pv-avance-20', 'Qualité, livraison, droit à l''image et contrôle final', 'Bloc E - Design et communication', '✅', 'Avancé', 'hybride', '4h + audit', 'Fouka', false, 'Effectuer un contrôle technique et éditorial, repérer erreur de nom, score, sponsor ou personne restreinte, livrer dans le bon format avec les bonnes permissions et conserver une preuve de validation.', array['photo']::text[], 2, true, 40),
  ('pv-avance-21', 'Projet final : produire une campagne complète SportVision de A à Z', 'Bloc F - Certification', '🏆', 'Avancé', 'hybride', '12h + soutenance', 'Fouka', false, 'Mobiliser toutes les compétences du parcours, travailler sous délai réel, livrer plusieurs formats cohérents et défendre ses choix techniques, créatifs et organisationnels devant le Responsable Production.', array['photo']::text[], 2, true, 41),
  ('sec-avance-01', 'Comprendre le nouvel écosystème SportVision', 'Secrétariat — Parcours avancé', '🧭', 'Avancé', 'hybride', '4h', 'Fouka', false, 'Expliquer la différence entre SportVision OS et SportVision Connect, identifier les parcours client (ponctuel, Club+, Full Communication, accompagnement spécialisé) et orienter chaque demande vers la bonne offre.', array['sec']::text[], null, true, 42),
  ('sec-avance-02', 'Utilisateurs, organisations, rôles et onboarding', 'Secrétariat — Parcours avancé', '🔐', 'Avancé', 'hybride', '5h', 'Fouka', false, 'Créer une organisation propre, inviter les utilisateurs avec le rôle minimal, gérer une personne présente dans plusieurs organisations et désactiver proprement un accès en fin de mission.', array['sec']::text[], null, true, 43),
  ('sec-avance-03', 'CRM, qualification et suivi commercial', 'Secrétariat — Parcours avancé', '📊', 'Avancé', 'hybride', '5h', 'Fouka', false, 'Qualifier une demande entrante, utiliser les statuts du pipeline sans créer de doublons, documenter chaque échange avec sa prochaine action et relancer avec méthode.', array['sec']::text[], null, true, 44),
  ('sec-avance-04', 'Parcours d''une prestation ponctuelle', 'Secrétariat — Parcours avancé', '📁', 'Avancé', 'hybride', '5h', 'Fouka', false, 'Traiter une réservation sans abonnement de bout en bout : vérification, devis, contrat, paiement, coordination avec la production et livraison dans Connect Essentiel.', array['sec']::text[], null, true, 45),
  ('sec-avance-05', 'Gérer Club+ Start et Club+ Performance', 'Secrétariat — Parcours avancé', '🏟️', 'Avancé', 'hybride', '5h', 'Fouka', false, 'Différencier Club+ Start et Performance, activer les droits correspondant au contrat, suivre les crédits et demandes, et gérer upgrade, downgrade, suspension et fin de contrat.', array['sec']::text[], null, true, 46),
  ('sec-avance-06', 'Full Communication et accompagnements spécialisés', 'Secrétariat — Parcours avancé', '🔄', 'Avancé', 'hybride', '5h', 'Fouka', false, 'Distinguer Full Communication, Club+ et accompagnements spécialisés (académie, coach, joueur, événement), créer un onboarding adapté au profil et suivre présences, validations et hors forfait.', array['sec']::text[], null, true, 47),
