  ('cm-complet-15', 'Metricool complet : planification, analyses, inbox, concurrence et rapports', 'Communication et réseaux sociaux — Formation complète', '📊', 'Intermédiaire', 'hybride', '12h', 'Fouka', false, 'Connecter et organiser plusieurs marques, programmer les contenus et utiliser les meilleurs horaires avec discernement, analyser performances et concurrence, créer des rapports clairs et automatisés, gérer inbox/SmartLinks/limites API.', array['cm']::text[], null, true, 101),
  ('cm-complet-16', 'Community management : commentaires, messages, modération et proximité', 'Communication et réseaux sociaux — Formation complète', '💬', 'Intermédiaire', 'hybride', '6h', 'Fouka', false, 'Répondre de manière rapide, humaine et cohérente, différencier question/critique/troll/menace/incident, créer des réponses enregistrées sans sembler robotique, transformer les interactions en relation et en opportunité.', array['cm']::text[], null, true, 102),
  ('cm-complet-17', 'Sponsors, Matchday, tournois et contenus en direct', 'Communication et réseaux sociaux — Formation complète', '🏆', 'Intermédiaire', 'hybride', '7h', 'Fouka', false, 'Valoriser les sponsors sans dégrader l''expérience éditoriale, préparer un dispositif Matchday ou événement, publier en direct avec rapidité et sécurité, produire un bilan de visibilité exploitable.', array['cm']::text[], null, true, 103),
  ('cm-complet-18', 'Algorithmes, KPI, reporting et amélioration continue', 'Communication et réseaux sociaux — Formation complète', '📈', 'Intermédiaire', 'hybride', '8h', 'Fouka', false, 'Comprendre ce qu''un algorithme de recommandation cherche à optimiser, choisir les KPI selon l''objectif, analyser les résultats sans conclure trop vite, mettre en place des tests et décisions mensuelles.', array['cm']::text[], null, true, 104),
  ('cm-complet-19', 'Sécurité, droits à l''image, mineurs et gestion de crise', 'Communication et réseaux sociaux — Formation complète', '🛡️', 'Intermédiaire', 'hybride', '7h', 'Fouka', false, 'Protéger les comptes et les accès, respecter les restrictions d''image et les données personnelles, réagir à un piratage/une erreur/une polémique, savoir quand arrêter de publier et escalader.', array['cm']::text[], null, true, 105),
  ('cm-complet-20', 'Organisation multi-clients, outils, automatisation et niveau Lead CM', 'Communication et réseaux sociaux — Formation complète', '👑', 'Intermédiaire', 'hybride', '6h', 'Fouka', false, 'Gérer plusieurs clients sans perdre en qualité, utiliser OS/Connect/Metricool/Canva/CapCut de manière structurée, construire routines/modèles/contrôles, comprendre les responsabilités d''un Lead CM.', array['cm']::text[], null, true, 106),
  ('cm-complet-21', 'Projet final de certification - Gestion complète des réseaux d''un club', 'Communication et réseaux sociaux — Formation complète', '🎓', 'Intermédiaire', 'hybride', '12h', 'Fouka', false, 'Prendre en charge un club fictif pendant quatre semaines, depuis l''onboarding jusqu''au reporting, en utilisant SportVision OS, Connect, Canva, CapCut, Meta Business Suite et Metricool.', array['cm']::text[], null, true, 107)
on conflict (id) do update set
  titre = excluded.titre, categorie = excluded.categorie, icone = excluded.icone,
  niveau = excluded.niveau, type = excluded.type, duree = excluded.duree,
  formateur = excluded.formateur, obligatoire = excluded.obligatoire,
  description = excluded.description, roles = excluded.roles,
  grade_minimum = excluded.grade_minimum, publiee = excluded.publiee, ordre = excluded.ordre;

