-- ── Contrôle : le catalogue et le barème doivent compter les mêmes leçons ─────────────────────

do $$
declare
  v_ecarts integer;
  v_detail text;
begin
  select count(*), string_agg(f.id || ' : ' || c.n || ' versées contre ' || r.total_lecons || ' attendues', ', ')
    into v_ecarts, v_detail
  from public.formations f
  join public.formation_rewards r on r.formation_id = f.id
  join (select formation_id, count(*)::int n from public.formation_lecons group by 1) c on c.formation_id = f.id
  where c.n is distinct from r.total_lecons;

  if v_ecarts > 0 then
    raise exception 'Le catalogue et formation_rewards ne comptent pas les mêmes leçons sur % formation(s) : %', v_ecarts, v_detail;
  end if;

  select count(*) into v_ecarts from public.formations f
    where not exists (select 1 from public.formation_lecons l where l.formation_id = f.id);
  if v_ecarts > 0 then
    raise exception '% formation(s) versée(s) sans une seule leçon.', v_ecarts;
  end if;
end $$;

commit;

select (select count(*) from public.formations) as formations,
       (select count(*) from public.formation_modules) as modules,
       (select count(*) from public.formation_lecons) as lecons,
       (select count(*) from public.formations where roles is null) as visibles_par_tous,
       (select count(*) from public.formations where grade_minimum is not null) as verrouillees_par_grade;
